CREATE OR REPLACE FUNCTION public.icash_next_before_closing_gaps()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare prior jsonb;g public.icash_seller_gaps;mid uuid;ticket public.icash_automation_tickets;f public.icash_seller_viewing_followups;
begin
 perform pg_advisory_xact_lock(726341927);
 update public.icash_seller_gaps set state='needs_review',updated_at=now() where state in ('open','queued','waiting') and expires_at<=now();
 prior:=public.icash_next_before_seller_recovery();if prior->>'token' is not null then return prior;end if;
 if not exists(select 1 from public.icash_operating_budget where id=1 and enabled) then return prior;end if;
 if exists(select 1 from public.icash_automation_tickets where kind='seller_recovery' and created_at>now()-interval '1 minute') then return prior;end if;
 for f in select followup.* from public.icash_seller_viewing_followups followup join public.icash_text_threads t on t.id=followup.buyer_thread_id and t.account_id=followup.account_id
  join public.icash_accounts a on a.id=followup.account_id and not a.bot_paused
  join public.icash_wallets w on w.account_id=a.id and w.balance_cents>0
  join pg_timezone_names tz on tz.name=t.timezone
  where followup.outgoing_id is null and followup.created_at>now()-interval '7 days' and public.icash_sms_outreach_window_current(t.account_id,t.id)
  order by followup.created_at for update of followup skip locked limit 20 loop
  mid:=public.icash_prepare_viewing_relay(f.request_id);
  if mid is not null then
   insert into public.icash_automation_tickets(account_id,kind,opener_message_id) values(f.account_id,'seller_recovery',mid) returning * into ticket;
   return jsonb_build_object('token',ticket.token);
  end if;
 end loop;
 for g in select gap.* from public.icash_seller_gaps gap join public.icash_text_threads t on t.id=gap.thread_id and t.account_id=gap.account_id
  join public.icash_accounts a on a.id=gap.account_id and not a.bot_paused
  join public.icash_wallets w on w.account_id=a.id and w.balance_cents>0
  join pg_timezone_names tz on tz.name=t.timezone
  where gap.state='open' and gap.due_at<=now() and gap.expires_at>now() and public.icash_sms_outreach_window_current(t.account_id,t.id)
  order by gap.due_at for update of gap skip locked limit 20 loop
  mid:=public.icash_prepare_seller_recovery(g.account_id,g.id);
  if mid is not null then
   insert into public.icash_automation_tickets(account_id,kind,opener_message_id) values(g.account_id,'seller_recovery',mid) returning * into ticket;
   return jsonb_build_object('token',ticket.token);
  end if;
  update public.icash_seller_gaps set due_at=now()+interval '1 hour',updated_at=now() where id=g.id and state='open';
 end loop;
 return prior;
end $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_paced_voice(p_account uuid, p_job uuid, p_rate uuid, p_permission_until timestamp with time zone, p_financial_checked_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_financial_eligible boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j public.icash_voice_jobs;p public.icash_voice_contact_targets;r public.icash_operation_rates;a jsonb;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select * into j from public.icash_voice_jobs where id=p_job and account_id=p_account for update;
 if not found or j.state<>'issued' then return false;end if;
 if (not public.icash_voice_outreach_hours_current(p_account,p_job) or not public.icash_seller_phone_call_current(p_account,p_job)) then return false;end if;
 select * into p from public.icash_voice_contact_targets where id=coalesce(j.permission_id,j.operational_contact_id) and account_id=p_account;
 select * into r from public.icash_operation_rates where id=p_rate;
 if p.id is null or p.party is distinct from 'seller' or r.id is null then return false;end if;
 if public.icash_voice_credit_bound(p_account,'voice:'||j.id,p_rate) is not null then
  r.charge_cents:=(public.icash_voice_credit_bound(p_account,'voice:'||j.id,p_rate)->>'charge_cents')::bigint;
 end if;

 if j.operational_contact_id is not null then
  if not public.icash_operational_contact_current(p_account,j.operational_contact_id,'voice',false)
   or not public.icash_claim_inventory(p_account,p.screening_id,p.phone) then return false;end if;
  p_permission_until:=least(p_permission_until,p.permission_until);
 end if;
 perform public.icash_reserve_operation(p_account,'voice:'||j.id,p_rate,p_permission_until,p_financial_checked_at,p_financial_eligible);
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_claim_cold_inventory(p_account uuid, p_screening uuid, p_phone text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare prop text;keys text[];k text;held public.icash_inventory_claims;contact text;
begin
 select snapshot->>'propertyId' into prop from public.icash_screening_jobs where id=p_screening and account_id=p_account;
 if prop is null or prop !~ '^prop_[A-Za-z0-9]+$' then return false;end if;
 if exists(select 1 from public.icash_outbound_property_owners where property_id=prop and account_id<>p_account) then return false;end if;
 keys:=array['property:'||prop];
 if p_phone is not null then
 if p_phone !~ '^[+][1-9][0-9]{7,14}$' then return false;end if;
 contact:=encode(extensions.digest(p_phone,'sha256'),'hex');
 if exists(select 1 from public.icash_text_suppressions where phone=p_phone) or exists(select 1 from public.icash_contact_suppressions where contact_key=contact) then return false;end if;
 keys:=array_append(keys,'phone:'||contact);
 end if;
 -- All callers share deterministic lock ordering. No partial claim on a denied pair.
 for k in select x from unnest(keys) x order by x loop perform pg_advisory_xact_lock(hashtextextended(k,219));end loop;
 for k in select x from unnest(keys) x order by x loop
 select * into held from public.icash_inventory_claims where resource_key=k;
 if found and held.account_id<>p_account and (
 held.cooldown_until>now()
 or exists(select 1 from public.icash_deal_files d join public.icash_screening_jobs s on s.id=d.screening_id where d.account_id=held.account_id and d.stage in ('under_contract','buyer_selected','title_open','closing') and s.snapshot->>'propertyId'=(select snapshot->>'propertyId' from public.icash_screening_jobs where id=held.screening_id))
 or exists(select 1 from public.icash_live_callbacks where account_id=held.account_id and screening_id=held.screening_id and state in ('pending_dispatch_review','held_for_human'))
 or exists(select 1 from public.icash_live_conversations where account_id=held.account_id and screening_id=held.screening_id and state in ('waiting','review'))
 ) then return false;end if;
 end loop;
 foreach k in array keys loop
 insert into public.icash_inventory_claims(resource_key,account_id,screening_id,cooldown_until) values(k,p_account,p_screening,now()+interval '30 days')
 on conflict(resource_key) do update set account_id=excluded.account_id,screening_id=excluded.screening_id,cooldown_until=excluded.cooldown_until,updated_at=now();
 end loop;
 return true;
end $function$
